const body = $input.item.json.body;
const normalized = body.normalized || {};
const texto = normalized.text_body || "";

// Anotacao de follow-up posta pela whatsapp-webhook (fase 13).
// valor_detectado preenchido = esta mensagem E a resposta (documento com
// digito verificador conferido). Preenchido so o id = ha pendencia aberta, mas
// a mensagem nao parece resposta; quem decide se e evidencia nova em texto
// livre e o classificador de intencao mais adiante.
const followup = body.followup || null;

// Como a pergunta pendente e descrita para o classificador de intencao.
//
// Sem isto ele classificava toda resposta em texto livre como despesa nova —
// "foi na clinica vida" e "nao tenho o cnpj, foi consulta particular" viravam
// registro_despesa em 9 de 9 mensagens medidas contra o Gemini real. O modo
// RECLASSIFICADO, que existe exatamente para essas frases, ficava inalcancavel:
// so o intent "outro" chega nele.
//
// O texto so entra no prompt quando ha pendencia aberta, entao a classificacao
// de quem nao tem pergunta pendente — a esmagadora maioria — continua byte a
// byte a de antes.
const CONTEXTO_FOLLOWUP = {
  documento_prestador: "o CNPJ ou CPF do prestador de uma despesa que ele ja registrou",
  estabelecimento: "onde foi uma despesa que ele ja registrou (o nome do estabelecimento)",
  valor_reembolso:
    "se uma despesa de saude que ele ja registrou foi reembolsada pelo plano, e de quanto foi esse reembolso",
};

// O discriminador tambem muda com o campo, e essa parte NAO podia continuar
// fixa no node do Gemini. O texto de identificacao termina com "NAO use esta
// categoria quando a mensagem trouxer o VALOR em dinheiro": na pergunta de
// reembolso o valor em dinheiro E a resposta certa, e a instrucao antiga
// empurraria a resposta de volta para registro_despesa — o mesmo bug 9/9 da
// fase anterior, com outra roupa.
const INSTRUCAO_FOLLOWUP = {
  documento_prestador:
    "Vale mesmo quando ela so diz o nome do lugar, quem atendeu, o tipo de servico, ou que o usuario nao tem o dado — a despesa ja esta registrada e o que falta e apenas a identificacao. NAO use esta categoria quando a mensagem trouxer o VALOR em dinheiro de um gasto novo: isso e registro_despesa.",
  estabelecimento:
    "Vale mesmo quando ela so diz o nome do lugar, quem atendeu, o tipo de servico, ou que o usuario nao tem o dado — a despesa ja esta registrada e o que falta e apenas a identificacao. NAO use esta categoria quando a mensagem trouxer o VALOR em dinheiro de um gasto novo: isso e registro_despesa.",
  valor_reembolso:
    "Vale mesmo quando ela so diz que houve ou que nao houve reembolso, quanto o plano cobriu, ou que o usuario ainda vai descobrir — a despesa ja esta registrada e o que falta e so o reembolso. NAO use esta categoria quando a mensagem descrever um gasto NOVO, com estabelecimento ou servico proprio: isso e registro_despesa.",
};

// Casa palavra-chave sem depender de acento nem de caixa.
const alvo = texto
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .toLowerCase();

const contem = (termos) => termos.some((t) => alvo.includes(t));

// Precedencia: o dossie e checado antes do resumo de proposito. "resumo" e
// palavra comum e apareceria em "manda o resumo em pdf", onde a intencao real
// e o arquivo. Os termos de dossie sao mais especificos, entao ganham.
//
// Conectar banco vem antes de todos, mas exigindo DOIS eixos na mesma
// mensagem: um verbo de conexao e um substantivo de conta/banco. Casar so
// "conta" ou so "banco" roubaria "me manda o resumo da minha conta" e
// "quanto rende o CDB do meu banco". O prefixo "conect"/"vincul" cobre as
// conjugacoes (conecta, conectar, vincule) sem depender de adjacencia.
// A guarda de "desconect"/"desvincul" existe porque "conect" casa dentro de
// "desconectar": desconexao nao esta implementada e cai na IA.
let intent = null;
if (contem(["desconect", "desvincul"])) {
  intent = null;
} else if (
  contem(["conect", "vincul", "sincroniz", "open finance"]) &&
  contem(["banco", "conta", "bancari", "cartao", "open finance"])
) {
  intent = "conectar_banco";
} else if (
  // Export estruturado para o contador, checado ANTES do dossie porque o
  // branch de dossie casa "exportar" — e "exportar para contador" cairia nele.
  //
  // Dois caminhos, com riscos de falso positivo diferentes:
  //
  // 1. planilha/excel/xlsx sao inequivocos. Nao existe outra coisa no TaxMind
  //    que seja uma planilha, entao a palavra sozinha basta.
  //
  // 2. "contador" sozinho NAO basta e nao pode bastar: "manda o dossie pro meu
  //    contador" e pedido de dossie, e "quanto paguei ao contador" e consulta.
  //    Por isso o segundo caminho exige um verbo de entrega junto E a AUSENCIA
  //    de termo de dossie — quem citou PDF/dossie explicitamente ja disse qual
  //    arquivo quer, e a mencao ao contador ali e o destinatario, nao o formato.
  contem(["planilha", "excel", "xlsx"]) ||
  (contem(["contador", "contabil"]) &&
    contem(["export", "envi", "mand", "gera", "prepar", "arquiv", "materi"]) &&
    !contem(["dossie", "pdf", "relatorio"]))
) {
  intent = "export_contador";
} else if (contem(["dossie", "relatorio", "pdf", "exportar"])) {
  intent = "exportar_dossie";
} else if (contem(["resumo", "extrato", "quanto tenho"])) {
  intent = "consulta_resumo";
} else if (
  // "Quem e voce / o que voce faz" cai por ultimo de proposito. As frases sao
  // longas o bastante para nao roubar lancamento ("comprei um robo" nao contem
  // "voce e um robo"), mas "como funciona" e generico: checado depois de
  // dossie/resumo/banco, "como funciona o dossie" continua sendo pedido de
  // dossie, que era o comportamento de antes. O classificador de IA cobre as
  // formas que a lista nao preve.
  contem([
    "quem e voce",
    "quem e vc",
    "quem e o taxmind",
    "o que e o taxmind",
    "o que e taxmind",
    "sobre o taxmind",
    "o que voce faz",
    "o que vc faz",
    "o que voce pode fazer",
    "o que vc pode fazer",
    "o que voce sabe fazer",
    "o que da pra fazer",
    "como voce funciona",
    "como vc funciona",
    "como funciona",
    "pra que serve",
    "para que serve",
    "voce e um robo",
    "vc e um robo",
    "voce e uma ia",
    "vc e uma ia",
  ])
) {
  intent = "sobre_o_taxmind";
}

return {
  json: {
    session_id: body.session_id || null,
    message_type: normalized.message_type || null,
    text_body: normalized.text_body || null,
    wa_id: normalized.wa_id,
    phone: normalized.phone,
    profile_name: normalized.profile_name || null,
    intent,
    followup_id: followup ? followup.id : null,
    followup_campo: followup ? followup.campo_alvo : null,
    followup_valor_detectado: followup ? followup.valor_detectado : null,
    followup_contexto: followup ? (CONTEXTO_FOLLOWUP[followup.campo_alvo] || null) : null,
    followup_instrucao: followup ? (INSTRUCAO_FOLLOWUP[followup.campo_alvo] || null) : null,
  },
};

const ctx = $('Preparar Contexto').item.json;
const resposta = $input.item.json;

// O PostgREST devolve array; o node HTTP pode ja ter desmembrado em item unico.
const linha = Array.isArray(resposta) ? resposta[0] : resposta;
const usuarioId = linha && linha.usuario_id ? linha.usuario_id : null;

// Mesma postura do outro workflow: falhar explicitamente e melhor do que gravar
// ou responder com vinculo errado quando o onboarding nao foi concluido.
if (!usuarioId) {
  throw new Error(
    "Sessao " + ctx.session_id + " sem usuario_id vinculado: onboarding nao concluido."
  );
}

return { json: { ...ctx, usuario_id: usuarioId } };

const ctx = $('Montar Contexto').item.json;
const resposta = $input.item.json;

const bruto = ((((resposta || {}).candidates || [])[0] || {}).content?.parts?.[0]?.text || "")
  .toLowerCase()
  .replace(/[^a-z_]/g, "");

// "outro" fica por ultimo de proposito: e o fallback, e find() retorna o
// primeiro match. As categorias especificas precisam ser testadas antes.
const validos = [
  "registro_despesa",
  "consulta_resumo",
  "exportar_dossie",
  "export_contador",
  "conectar_banco",
  "resposta_de_followup",
  "fora_do_escopo_financeiro",
  "sobre_o_taxmind",
  "outro",
];

// Gemini 3 Flash nao permite desligar thinking (so thinkingLevel minimal/low/
// medium/high). Se o thinking consumir o maxOutputTokens, o texto volta vazio.
// Cair em "outro" mantem o fluxo vivo com a mensagem de ajuda, em vez de
// derrubar a execucao com intent indefinido.
const intent = validos.find((v) => bruto.includes(v)) || "outro";

return { json: { ...ctx, intent } };

const ctx = $('Montar Contexto').first().json;
const linhas = $input.all().map((i) => i.json);

const emojiPorCategoria = {
  SAUDE: "\u{1F3E5}",
  EDUCACAO: "\u{1F393}",
  ALIMENTACAO: "\u{1F37D}\u{FE0F}",
  TRANSPORTE: "\u{1F697}",
  MORADIA: "\u{1F3E0}",
  ESCRITORIO: "\u{1F5C2}\u{FE0F}",
  EQUIPAMENTOS: "\u{1F5A5}\u{FE0F}",
  SOFTWARE: "\u{1F4BE}",
  INTERNET_TELEFONIA: "\u{1F4F6}",
  SERVICOS_PROFISSIONAIS: "\u{1F4BC}",
  IMPOSTOS_TAXAS: "\u{1F9FE}",
  OUTROS: "\u{1F4CC}",
};

const brl = (v) =>
  Number(v || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

const validas = linhas.filter((l) => l && l.categoria);

if (validas.length === 0) {
  return {
    json: {
      ...ctx,
      mensagem:
        "Voce ainda nao tem despesas registradas. Manda a foto de um cupom ou descreve a despesa por texto que eu registro pra voce.",
    },
  };
}

let totalGeral = 0;
let totalDedutivel = 0;
let totalPendente = 0;

const blocos = validas.map((l) => {
  totalGeral += Number(l.total || 0);
  totalDedutivel += Number(l.total_dedutivel || 0);
  totalPendente += Number(l.pendente_revisao || 0);

  const emoji = emojiPorCategoria[l.categoria] || emojiPorCategoria.OUTROS;
  const nome =
    l.categoria.charAt(0) + l.categoria.slice(1).toLowerCase().split("_").join(" ");
  return emoji + " " + nome + ": " + brl(l.total) + " (" + l.quantidade + ")";
});

const partes = [
  "*Seu resumo fiscal*",
  blocos.join("\n"),
  "*Total:* " + brl(totalGeral),
  "*Dedutivel:* " + brl(totalDedutivel),
];

// Deducao reduz a base de calculo do IR, nao o imposto devido. Sem esta
// linha o total dedutivel acima e lido como dinheiro de volta.
if (totalDedutivel > 0) {
  partes.push(
    "O valor dedutivel reduz sua base de calculo do IR \u2014 a economia real depende da sua faixa de tributacao, nao e o valor que voce recebe de volta."
  );
}

if (totalPendente > 0) {
  partes.push(
    "\u{23F3} " +
      totalPendente +
      (totalPendente === 1 ? " lancamento aguarda" : " lancamentos aguardam") +
      " revisao humana."
  );
}

partes.push("Quer o PDF completo? Manda *dossie*.");

return { json: { ...ctx, mensagem: partes.join("\n\n") } };

